import heapq
class Solution:
    def resultsArray(self, queries, k):
        h = []
        res = []
        for x, y in queries:
            d = abs(x) + abs(y)
            if len(h) < k:
                heapq.heappush(h, -d)
            elif d < -h[0]:
                heapq.heapreplace(h, -d)
            res.append(-h[0] if len(h) == k else -1)
        return res

