class Solution {
public:
    vector<int> resultsArray(vector<vector<int>>& queries, int k) {
        priority_queue<int> h;
        vector<int> res;
        for (auto& q : queries) {
            int d = abs(q[0]) + abs(q[1]);
            if (h.size() < k) h.push(d);
            else if (d < h.top()) { h.pop(); h.push(d); }
            res.push_back(h.size() == k ? h.top() : -1);
        }
        return res;
    }
};

